// m2a: convert MIT format annotation files to AHA DB distribution tape
// format (port of convert/m2a.c, through rust/src/bin/m2a.rs).
//
// The files generated by this program are in the format formerly used for
// distribution of the AHA and MIT-BIH databases on half-inch 9-track digital
// tape. It does *not* generate files in the format currently used for
// distribution of the AHA database on floppy disk; a2m can perform the
// reverse conversion, however.
//
// This file is part of WFDB-x, an independent reimplementation of the WFDB
// Software Package in Python, C++, MATLAB/Octave, Rust, Julia, R and Kotlin.
//
// It is a Kotlin translation of convert/m2a.c from the WFDB Software Package
// 10.7.0, by George B. Moody. The translation follows the logic and behavior
// of the original program, but it is new code, not the original C code.
//
// Changes from the original: no built-in sampling frequency: the new option -F
// FREQ gives it when the record header gives none, and is then required for -s
// (the original assumed 250 Hz); --legacy, as the first argument, restores the
// original behavior. Each change is marked "wfdb-x:" in the code;
// docs/DIVERGENCES.md gives the reasons.
//
// Original C program: convert/m2a.c, WFDB Software Package 10.7.0.
//   Copyright (C) 2001 George B. Moody.
// Kotlin translation and changes: Copyright (C) 2026 Reza Sameni.
//
// This program is free software: you can redistribute it and/or modify it
// under the terms of the GNU General Public License as published by the Free
// Software Foundation, either version 3 of the License, or (at your option)
// any later version. See LICENSE.

package wfdbx.apps

import wfdbx.*
import wfdbx.cstd.*

private val M2A_HELP = arrayOf(
    "usage: %s -r RECORD -a MIT-ANNOTATOR AHA-ANNOTATOR [ OPTIONS ... ]\n",
    "where RECORD is the record name, MIT-ANNOTATOR is the annotator name",
    "for the input annotation file, AHA-ANNOTATOR is the annotator name",
    "for the output (AHA format) annotation file, and OPTIONS may include:",
    " -F FREQ   sampling frequency, if the record header does not specify one",
    " -h        print this usage summary",
    " -s TIME   shift annotation times backwards by the specified TIME,",
    "            and convert them to milliseconds",
)

/** wfdb-x: the help lines added by WFDB-x (left out in legacy mode). */
private val M2A_WFDBX_HELP = setOf(
    " -F FREQ   sampling frequency, if the record header does not specify one",
)

private fun Wfdb.m2aHelp(pname: ByteArray) {
    val legacy = wfdbx_get_legacy() != 0
    eprintf(M2A_HELP[0], pname)
    for (k in 1 until M2A_HELP.size) {
        val s = M2A_HELP[k]
        if (!(legacy && s in M2A_WFDBX_HELP)) eprintf("%s\n", s)
    }
}

/** The m2a tool. */
fun Wfdb.m2aMain(argv0: Array<ByteArray>): Int {
    val argv = toolArgv(argv0)
    val legacy = wfdbx_get_legacy() != 0
    val argc = argv.size
    val pname = progName(argv[0])
    var ianame: ByteArray? = null
    var oaname: ByteArray? = null
    var record: ByteArray? = null
    var shift: ByteArray? = null
    val ffreq = CDouble(0.0) // -F (WFDB-x)
    val annot = Annotation()

    var i = 1
    while (i < argc) {
        val a = argv[i]
        if (a.at(0) == '-'.code) {
            when (a.at(1).toChar()) {
                'a' -> { // annotator names follow
                    i++
                    if (i + 1 >= argc) {
                        eprintf("%s: input and output annotator names must follow -a\n", pname)
                        exit(1)
                    }
                    ianame = argv[i]
                    i++
                    oaname = argv[i]
                }
                'F' -> {
                    if (legacy) {
                        eprintf("%s: unrecognized option %s\n", pname, a)
                        exit(1)
                    }
                    // sampling frequency follows (WFDB-x)
                    i++
                    if (i >= argc || sscanf(argv[i], "%lf", ffreq) != 1 || ffreq.v <= 0.0) {
                        eprintf("%s: sampling frequency (> 0) must follow -F\n", pname)
                        exit(1)
                    }
                }
                'h' -> { // help requested
                    m2aHelp(pname)
                    exit(1)
                }
                'r' -> { // record name follows
                    i++
                    if (i >= argc) {
                        eprintf("%s: record name must follow -r\n", pname)
                        exit(1)
                    }
                    record = argv[i]
                }
                's' -> { // shift follows
                    i++
                    if (i >= argc) {
                        eprintf("%s: time shift must follow -s\n", pname)
                        exit(1)
                    }
                    shift = argv[i]
                }
                else -> {
                    eprintf("%s: unrecognized option %s\n", pname, a)
                    exit(1)
                }
            }
        } else {
            eprintf("%s: unrecognized argument %s\n", pname, a)
            exit(1)
        }
        i++
    }
    if (ianame == null || oaname == null || record == null) {
        m2aHelp(pname)
        exit(1)
    }

    val afarray = arrayOf(Anninfo(cstr(ianame), WFDB_READ), Anninfo(cstr(oaname), WFDB_AHA_WRITE))
    if (annopen(record, afarray, 2) < 0) exit(2) // open files
    if (shift == null) {
        // copy annotations to end of data
        while (getann(0, annot) >= 0) putann(0, annot)
    } else {
        // wfdb-x: no default sampling frequency (the C program assumed
        // 250 Hz if the record header did not specify one, as legacy mode
        // does); -F specifies one.
        if (sampfreq(record) <= 0.0) {
            if (legacy) {
                setsampfreq(WFDB_DEFFREQ)
            } else if (ffreq.v > 0.0) {
                setsampfreq(ffreq.v)
            } else {
                eprintf("%s: sampling frequency of record %s is not specified (use -F)\n", pname, record)
                exit(1)
            }
        }
        // milliseconds per sample interval
        val mssi = 1000.0 / strtim("1").toDouble()
        val dt = strtim(shift)
        while (getann(0, annot) >= 0) {
            if (annot.time >= dt) {
                annot.time = d2l((annot.time - dt).toDouble() * mssi)
                putann(0, annot)
            }
        }
    }

    wfdbquit()
    exit(0)
}
